SELECT "LOOKUP_SEASON"."ID", "LOOKUP_SEASON"."YEAR", "LOOKUP_SEASON"."GT", "LOOKUP_SEASON"."NULLED_TEXT_FIELD", ((SELECT (1) AS "A" FROM "LOOKUP_SEASON" U0 WHERE (U0."ID" = ("LOOKUP_SEASON"."ID") AND U0."YEAR" < %s) FETCH FIRST 1 ROWS ONLY) IS NOT NULL) AS "BEFORE_20" FROM "LOOKUP_SEASON" WHERE CASE WHEN ((SELECT (1) AS "A" FROM "LOOKUP_SEASON" U0 WHERE (U0."ID" = ("LOOKUP_SEASON"."ID") AND U0."YEAR" < %s) FETCH FIRST 1 ROWS ONLY) IS NOT NULL) THEN TRUE ELSE FALSE END = (CASE WHEN "LOOKUP_SEASON"."YEAR" < CAST(%s AS INTEGER) THEN TRUE ELSE FALSE END);
